// The settings codec against the REAL firmware code: ui/tests/vectors/settings_vectors.json is generated by
// firmware/tools/gen_settings_vector.py from km_settings.c (nothing is pasted by hand). Regenerate it after any change there.
import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { encodeSettings, encodeSettingsV2, encodeSettingsV3, decodeSettings, needsV3, SettingsError, rawCfgProblem, defaultRawSettings, defaultRawCfg, cloneRaw } from "../js/core/settings_codec.js";
import { usageCodeValid, entryProblem, entryNeedsV3, optsProblem, FW_SETTINGS, FW_USAGE_RULE_V2, FW_KEY_SLOTS, FW_NO_KEY_SLOTS } from "../js/core/limits.js";
import { crc32 } from "../js/device/config_protocol.js";

const V = JSON.parse(readFileSync(new URL("./vectors/settings_vectors.json", import.meta.url), "utf8"));
const hex = (b) => Buffer.from(b).toString("hex");
const bytes = (h) => Uint8Array.from(Buffer.from(h, "hex"));

test("vector file is the size the format says", () => {
  assert.equal(V.size, FW_SETTINGS.size);
  assert.equal(V.v1_size, FW_SETTINGS.v1Size);
  assert.equal(FW_SETTINGS.version, 3);
  assert.equal(FW_SETTINGS.v2Version, 2);
  assert.equal(V.v3.max_size, FW_SETTINGS.v3MaxSize);
  assert.equal(V.v3.keys, FW_SETTINGS.keys);
  assert.equal(V.default.length, 2 * V.size);
  assert.equal(V.crc_check_123456789, "cbf43926");
  assert.equal(crc32(new TextEncoder().encode("123456789")), 0xcbf43926);
});

test("the firmware's own default blob decodes, and re-encodes to the same bytes", () => {
  const s = decodeSettings(bytes(V.default));
  assert.equal(s.active, 0);
  assert.equal(s.profiles.length, 4);
  assert.deepEqual(s.profiles[0].keys[0], { press: 120, release: 80, mode: 0, continuous: 0, rtDown: 30, rtUp: 30, topDead: 0, bottomDead: 0 }); // km_engine_key_cfg_default
  assert.equal(hex(encodeSettings(s)), V.default);
});

test("the key map's default table (Fn holds layer 1, overlay entries 0xFF) is a valid blob and round-trips", () => {
  const s = decodeSettings(bytes(V.default_table));
  assert.equal(hex(encodeSettings(s)), V.default_table);
  assert.equal(s.profiles[0].layers[0][14], 0xf0, "Fn on layer 0 holds layer 1");
  assert.equal(s.profiles[0].layers[2][5], 0xff, "layer 2 is all transparent");
  assert.equal(s.profiles[0].layers[0][14], 0xf0);
});

test("the same table with transparent written out (what a firmware that stops at 0xFA would need) still round-trips", () => {
  const s = decodeSettings(bytes(V.default_flattened));
  assert.equal(hex(encodeSettings(s)), V.default_flattened);
  assert.ok(s.profiles[0].layers.every((l) => l.every((c) => c !== 0xff)));
});

for (const c of V.cases) {
  test(`case ${c.name}: JS output is byte-identical to the firmware's (or both refuse)`, () => {
    const s = decodeSettings(bytes(V.default));
    s.active = c.active;
    for (const [p, slot, cfg] of c.cfgs) s.profiles[p].keys[slot] = { ...cfg };
    for (const [p, l, slot, v, a0, a1] of c.usages) { s.profiles[p].layers[l][slot] = v; s.profiles[p].args[l][slot] = [a0, a1]; }
    for (const [p, tapTerm, oneshot, policy] of c.opts) s.profiles[p].opts = { tapTerm, oneshot, policy };
    if (c.encoded === null) {
      assert.throws(() => encodeSettings(s), SettingsError, "the firmware refuses this, so must the codec");
    } else {
      const out = encodeSettings(s);
      assert.equal(hex(out), c.encoded);
      assert.deepEqual(decodeSettings(out), s, "decode(encode(x)) == x");
    }
  });
}

test("usage-byte rule equals the firmware's for all 256 values", () => {
  for (let u = 0; u < 256; u++) assert.equal(usageCodeValid(u), V.usage_valid[u] === 1, `usage 0x${u.toString(16)}`);
});

test("table-entry rule (code + two argument bytes) equals the firmware's on every probe, including all 256 bare codes", () => {
  assert.ok(V.entry_probes.length > 280);
  for (const p of V.entry_probes) {
    assert.equal(entryProblem(p.code, p.arg0, p.arg1) === null, p.valid, p.name);
    assert.equal(entryProblem(p.code, p.arg0, p.arg1, FW_USAGE_RULE_V2) === null, p.valid_v2, `${p.name} (format 2 rule)`);
    assert.equal(entryNeedsV3(p.code, p.arg0, p.arg1), p.valid && !p.valid_v2, `${p.name} (needs format 3)`);
  }
});

test("layer-options rule equals the firmware's on every probe", () => {
  assert.ok(V.opts_probes.length >= 15);
  for (const p of V.opts_probes) assert.equal(optsProblem({ tapTerm: p.tapTerm, oneshot: p.oneshot, policy: p.policy }) === null, p.valid, p.name);
});

test("version 1 blobs are read and migrated exactly like the firmware does (arguments 0, default options), or refused like it", () => {
  assert.ok(V.migrations.length >= 10);
  for (const m of V.migrations) {
    const b = bytes(m.v1);
    if (m.migrated === null) {
      assert.throws(() => decodeSettings(b), SettingsError, m.name);
    } else {
      const s = decodeSettings(b);
      assert.equal(s.version, 3, "the model is always the newest version");
      assert.equal(hex(encodeSettings(s)), m.migrated, m.name);
      for (const p of s.profiles) {
        assert.deepEqual(p.opts, { tapTerm: 200, oneshot: 2000, policy: 0 });
        assert.ok(p.args.every((l) => l.every((a) => a[0] === 0 && a[1] === 0)));
      }
    }
  }
  assert.equal(decodeSettings(bytes(V.migrations[0].v1)).profiles[0].layers[0][14], 0xf0, "the Fn key survives the migration");
});

test("key-config rule equals the firmware's on every boundary probe", () => {
  for (const p of V.cfg_probes) assert.equal(rawCfgProblem(p.cfg) === null, p.valid, p.name);
});

function mutate(m) {
  let b = bytes(V.default);
  if (m.fill) b = new Uint8Array(b.length).fill(parseInt(m.fill, 16));
  for (const [off, h] of m.patches) b.set(bytes(h), off);
  if (m.recrc) {
    const c = crc32(b.subarray(0, b.length - 4));
    b.set([c & 255, (c >>> 8) & 255, (c >>> 16) & 255, c >>> 24], b.length - 4);
  }
  if (m.truncate !== undefined) b = b.slice(0, m.truncate);
  if (m.extend) b = Uint8Array.from([...b, ...new Array(m.extend).fill(0)]);
  return b;
}

for (const m of V.mutations) {
  test(`corrupted blob ${m.name}: ${m.accepted ? "accepted" : "refused"} like the firmware`, () => {
    const b = mutate(m);
    if (m.accepted) {
      const s = decodeSettings(b);
      assert.equal(hex(encodeSettings(s)), hex(b));
    } else {
      assert.throws(() => decodeSettings(b), SettingsError);
    }
  });
}

test("refusals carry a reason a person can be told", () => {
  const code = (name) => {
    try { decodeSettings(mutate(V.mutations.find((m) => m.name === name))); } catch (e) { return e.code; }
    return null;
  };
  assert.equal(code("empty"), "short");
  assert.equal(code("truncated_to_15"), "short");
  assert.equal(code("truncated_by_one"), "length");
  assert.equal(code("all_ff"), "magic");
  assert.equal(code("bad_magic"), "magic");
  assert.equal(code("bit_flip_no_crc_fix"), "crc");
  assert.equal(code("version_3"), "shape", "a version 2 body labelled 3 is read as version 3 and its header says 76 slots");
  assert.equal(code("version_1_label_on_v2_body"), "length");
  assert.equal(code("usage_E8_without_args"), "usage");
  assert.equal(code("arg_on_plain_key"), "usage");
  assert.equal(code("opts_tap_term_29"), "opts");
  assert.equal(code("opts_oneshot_99"), "opts");
  assert.equal(code("opts_policy_3"), "opts");
  assert.equal(code("opts_reserved_1"), "opts");
  assert.equal(code("length_field_wrong"), "length");
  assert.equal(code("profiles_3"), "shape");
  assert.equal(code("mode_2"), "cfg");
  assert.equal(code("usage_01_layer0"), "usage");
  assert.equal(code("active_4"), "range");
});

test("a model without argument bytes or layer options is a shape error, a bad option is an opts error", () => {
  const s = defaultRawSettings();
  const noArgs = cloneRaw(s);
  delete noArgs.profiles[0].args;
  assert.throws(() => encodeSettings(noArgs), (e) => e.code === "shape");
  const badOpts = cloneRaw(s);
  badOpts.profiles[3].opts.tapTerm = 10;
  assert.throws(() => encodeSettings(badOpts), (e) => e.code === "opts" && e.where.profile === 3);
  const badEntry = cloneRaw(s);
  badEntry.profiles[0].layers[1][5] = 0xe9;           // tap-hold without arguments
  assert.throws(() => encodeSettings(badEntry), (e) => e.code === "usage" && e.where.layer === 1 && e.where.slot === 5);
  badEntry.profiles[0].args[1][5] = [0x2c, 0xe0];
  assert.doesNotThrow(() => encodeSettings(badEntry));
});

test("decode does not accept plain arrays of the wrong thing or null", () => {
  assert.throws(() => decodeSettings(null), SettingsError);
  assert.throws(() => decodeSettings([1, 2, 3]), (e) => e.code === "short");
});

test("encode refuses a model that is not 4 profiles x 4 layers x 76 slots", () => {
  const s = defaultRawSettings();
  const bad = cloneRaw(s);
  bad.profiles.pop();
  assert.throws(() => encodeSettings(bad), (e) => e.code === "shape");
  const bad2 = cloneRaw(s);
  bad2.profiles[2].layers[3].pop();
  assert.throws(() => encodeSettings(bad2), (e) => e.code === "shape");
  const bad3 = cloneRaw(s);
  bad3.profiles[1].keys[7].press = 1.5;
  assert.throws(() => encodeSettings(bad3), (e) => e.code === "cfg" && e.where.profile === 1 && e.where.slot === 7);
});


// ======================================================================= settings format version 3 (M6 task P0)

const V3 = V.v3;
const kslot = FW_KEY_SLOTS;

/** Replay the commands the generator gave the real writer on the raw model; false when a command cannot be said in the model (a reserved byte that is not 0). */
function applyCmds(s, cmds) {
  const zeroDks = () => ({ tAct: 0, tBot: 0, flags: 0, acts: [[0, 0], [0, 0], [0, 0], [0, 0]] });
  const grow = (list, i, make) => { while (list.length <= i) list.push(make()); };
  const setCount = (list, n, make) => { while (list.length < n) list.push(make()); list.length = n; };
  for (const [op, p, ...a] of cmds) {
    const pr = s.profiles[p & 3];
    switch (op) {
      case "cfg": { const [slot, press, release, mode, continuous, rtDown, rtUp, topDead, bottomDead] = a; pr.keys[slot] = { press, release, mode, continuous, rtDown, rtUp, topDead, bottomDead }; break; }
      case "ent": { const [l, slot, code, a0, a1] = a; pr.layers[l][slot] = code; pr.args[l][slot] = [a0, a1]; break; }
      case "opt": pr.opts = { tapTerm: a[0], oneshot: a[1], policy: a[2] }; break;
      case "dks": {
        const [i, tAct, tBot, flags, u0, e0, u1, e1, u2, e2, u3, e3, rsvd] = a;
        if (rsvd) return false;
        grow(pr.dks, i, zeroDks);
        pr.dks[i] = { tAct, tBot, flags, acts: [[u0, e0], [u1, e1], [u2, e2], [u3, e3]] };
        break;
      }
      case "dksn": setCount(pr.dks, a[0], zeroDks); break;
      case "morph": if (a[4]) return false; grow(pr.morph, a[0], () => ({ mask: 0, usage: 0, flags: 0 })); pr.morph[a[0]] = { mask: a[1], usage: a[2], flags: a[3] }; break;
      case "morphn": setCount(pr.morph, a[0], () => ({ mask: 0, usage: 0, flags: 0 })); break;
      case "socd": grow(pr.socd, a[0], () => ({ a: 0, b: 0, mode: 0, flags: 0 })); pr.socd[a[0]] = { a: a[1], b: a[2], mode: a[3], flags: a[4] }; break;
      case "socdn": setCount(pr.socd, a[0], () => ({ a: 0, b: 0, mode: 0, flags: 0 })); break;
      case "pad": pr.pad.curves[a[0]] = { start: a[1], end: a[2], shape: a[3], flags: a[4] }; break;
      case "padopt": if (a[3]) return false; pr.pad.deadzone = a[0]; pr.pad.circular = a[1]; pr.pad.smooth = a[2]; break;
      case "dev": if (p !== undefined && a[1]) return false; s.device = { padMode: p, filterMode: a[0] }; break;
      default: throw new Error(`unknown command ${op}`);
    }
  }
  return true;
}

/** What a version 3 round trip gives back: slots without a key are the factory default again. */
function dropNonKeySlots(s) {
  const out = cloneRaw(s);
  for (const pr of out.profiles) {
    for (const slot of FW_NO_KEY_SLOTS) {
      pr.keys[slot] = defaultRawCfg();
      for (let l = 0; l < 4; l++) { pr.layers[l][slot] = 0; pr.args[l][slot] = [0, 0]; }
    }
  }
  return out;
}

const base2 = () => decodeSettings(bytes(V.default));
const noUnknown = (s) => { s.unknown = []; return s; };

test("v3: the slots that carry a key are the ones the firmware says, and the numbers of the format agree", () => {
  assert.equal(V3.key_slots_flags.length, 76);
  for (let i = 0; i < 76; i++) assert.equal(kslot.includes(i), V3.key_slots_flags[i] === "1", `slot ${i}`);
  assert.equal(kslot.length, 61);
  assert.equal(FW_NO_KEY_SLOTS.length, 15);
  assert.equal(FW_SETTINGS.v3MaxEncoded, 7308);
});

test("v3: the firmware's default settings written as sections, byte for byte, and read back", () => {
  const s = base2();
  assert.equal(hex(encodeSettingsV3(s)), V3.default_v3);
  assert.deepEqual(decodeSettings(bytes(V3.default_v3)), s);
  assert.equal(V3.default_v3.length / 2, 16 + 4 + 4 * (4 + 854 + 4 + 738));
  assert.equal(hex(encodeSettings(s)), V.default, "but nothing needs version 3, so the lowest version is written");
  assert.equal(needsV3(s), false);
  // the model of defaults is the same as the decoded default blob (pad curves, device options, empty lists)
  const d = defaultRawSettings(0);
  d.profiles.forEach((pr, p) => { pr.layers = s.profiles[p].layers; });
  assert.deepEqual(d, s);
});

for (const c of V3.cases) {
  test(`v3 case ${c.name}: byte-identical to the firmware's writer, same version, or both refuse`, () => {
    const s = base2();
    s.active = c.active;
    const ok = applyCmds(s, c.cmds);
    if (!ok) { assert.equal(c.encoded, null, "a reserved byte that is not 0 is something only the firmware can be told"); return; }
    if (c.encoded === null) {
      assert.throws(() => encodeSettings(s), SettingsError, "the firmware refuses this, so must the codec");
      return;
    }
    const out = encodeSettings(s);
    assert.equal(hex(out), c.encoded);
    const want = out[4] === 3 ? dropNonKeySlots(s) : s;
    assert.deepEqual(decodeSettings(out), want, "decode(encode(x)) == x");
    assert.equal(needsV3(s), out[4] === 3);
    if (out[4] === 3) assert.throws(() => encodeSettingsV2(s), SettingsError, "version 2 cannot hold it");
    assert.ok(out.length <= FW_SETTINGS.v3MaxEncoded || out[4] === 2);
  });
}

test("v3: the version the writer picks follows the rule: 2 unless something needs 3", () => {
  const v = Object.fromEntries(V3.cases.map((c) => [c.name, c.encoded && parseInt(c.encoded.slice(8, 10), 16)]));
  assert.equal(v.v3_none_default, 2);
  assert.equal(v.v3_light_action_zero_stays_v2, 2);
  assert.equal(v.v3_nonkey_slot_data_stays_v2, 2);
  assert.equal(v.v3_tap_hold_modifier_same_stays_v2, 2);
  for (const n of ["v3_nonkey_slot_data_dropped", "v3_dks_one", "v3_morph", "v3_socd_two_pairs", "v3_pad_curve", "v3_pad_option", "v3_device_pad", "v3_device_filter",
    "v3_code_toggle_key", "v3_code_pad_btn", "v3_code_pad_axis", "v3_code_light", "v3_code_tap_hold_key_hold", "v3_everything"]) assert.equal(v[n], 3, n);
  assert.ok(V3.cases.filter((c) => c.name.startsWith("reject_")).every((c) => c.encoded === null));
  assert.ok(V3.cases.filter((c) => c.name.startsWith("reject_")).length >= 50);
});

test("v3: the largest blob is 7308 bytes, below the 8176 a store record holds", () => {
  const big = V3.cases.find((c) => c.name === "v3_everything").encoded.length / 2;
  assert.ok(big <= FW_SETTINGS.v3MaxEncoded && big < FW_SETTINGS.v3MaxSize && big < FW_SETTINGS.size);
  const s = base2();
  for (const pr of s.profiles) {
    pr.dks = Array.from({ length: 8 }, (_, i) => ({ tAct: 60 + i, tBot: 200, flags: 1, acts: [[4 + i, 255], [0, 0], [0, 0], [0, 0]] }));
    pr.morph = Array.from({ length: 8 }, (_, i) => ({ mask: 1 << i, usage: 4, flags: 0 }));
    pr.socd = [0, 1, 2, 3].map((i) => ({ a: kslot[2 * i], b: kslot[2 * i + 1], mode: 1, flags: 0 }));
    pr.pad.curves[0].shape = 2;
  }
  s.device.padMode = 1;
  assert.equal(encodeSettings(s).length, FW_SETTINGS.v3MaxEncoded);
});

test("v3: the entry rules equal the firmware's for every (code, argument 0, argument 1) of the codes that matter, in both versions", () => {
  const bit = (hexRow, a0, a1) => (parseInt(hexRow[a0 * 64 + (a1 >> 2)], 16) >> (a1 & 3)) & 1;
  let checked = 0, validCount = 0;
  for (const [code, row] of Object.entries(V3.entry_maps_v3)) {
    assert.equal(row.length, 256 * 64);
    for (let a0 = 0; a0 < 256; a0++) {
      for (let a1 = 0; a1 < 256; a1++) {
        const want = bit(row, a0, a1) === 1;
        if (entryProblem(Number(code), a0, a1) === null !== want) assert.fail(`code ${code} args ${a0},${a1}: firmware says ${want}`);
        checked++; validCount += want;
      }
    }
  }
  for (const [code, row] of Object.entries(V3.entry_maps_v2)) {
    for (let a0 = 0; a0 < 256; a0++) {
      for (let a1 = 0; a1 < 256; a1++) {
        if ((entryProblem(Number(code), a0, a1, FW_USAGE_RULE_V2) === null) !== (bit(row, a0, a1) === 1)) assert.fail(`format 2 rule: code ${code} args ${a0},${a1}`);
      }
    }
  }
  assert.equal(checked, 10 * 65536);
  assert.ok(validCount > 10000);
});

function patchedBlob(base, m) {
  let b = Uint8Array.from(base);
  if (m.fill) b = new Uint8Array(b.length).fill(parseInt(m.fill, 16));
  for (const [off, h] of m.patches) b.set(bytes(h), off);
  if (m.recrc) {
    const c = crc32(b.subarray(0, b.length - 4));
    b.set([c & 255, (c >>> 8) & 255, (c >>> 16) & 255, c >>> 24], b.length - 4);
  }
  if (m.truncate !== undefined) {
    b = b.slice(0, m.truncate);
    if (m.fixlen) {
      if (b.length >= 8) { b[6] = b.length & 255; b[7] = b.length >> 8; }
      if (b.length >= 4) { const c = crc32(b.subarray(0, b.length - 4)); b.set([c & 255, (c >>> 8) & 255, (c >>> 16) & 255, c >>> 24], b.length - 4); }
    }
  }
  if (m.extend) b = Uint8Array.from([...b, ...new Array(m.extend).fill(0)]);
  return b;
}

function sameAsFirmware(b, reencoded, name) {
  if (reencoded === null) {
    assert.throws(() => decodeSettings(b), SettingsError, `${name}: the firmware refuses this`);
    return;
  }
  const s = noUnknown(decodeSettings(b));
  assert.equal(hex(encodeSettings(s)), reencoded, `${name}: read and written again`);
}

const richBlob = bytes(V3.cases.find((c) => c.name === "v3_everything").encoded);

for (const m of V3.mutations) {
  test(`v3 damaged blob ${m.name}: ${m.reencoded === null ? "refused" : "accepted"} like the firmware`, () => {
    sameAsFirmware(patchedBlob(richBlob, m), m.reencoded, m.name);
  });
}

for (const m of V3.blobs) {
  test(`v3 built blob ${m.name}: ${m.reencoded === null ? "refused" : "accepted"} like the firmware`, () => {
    sameAsFirmware(bytes(m.blob), m.reencoded, m.name);
  });
}

test("v3: the generated vectors really contain both outcomes in good number", () => {
  const all = [...V3.mutations, ...V3.blobs];
  assert.ok(all.filter((m) => m.reencoded !== null).length >= 20, "accepted");
  assert.ok(all.filter((m) => m.reencoded === null).length >= 100, "refused");
  assert.ok(V3.mutations.length >= 140 && V3.blobs.length >= 30);
});

test("v3: unknown optional sections are kept by the codec and written back; the firmware drops them", () => {
  const built = V3.blobs.find((b) => b.name === "v3_unknown_optional_per_profile");
  const s = decodeSettings(bytes(built.blob));
  assert.deepEqual(s.unknown.map((u) => [u.id, u.scope, u.bytes.length]), [[0x82, 0, 0], [0x83, 1, 20], [0x84, 2, 40], [0x85, 3, 60]]);
  assert.equal(needsV3(s), true, "they only fit in version 3");
  const out = encodeSettings(s);
  assert.equal(out[4], 3);
  assert.deepEqual(decodeSettings(out), s, "kept, byte for byte");
  assert.notEqual(hex(out), built.reencoded);
  assert.equal(hex(encodeSettings(noUnknown(s))), built.reencoded, "without them it is what the firmware writes");
  // the bytes of an unknown section are not looked at
  const front = decodeSettings(bytes(V3.blobs.find((b) => b.name === "v3_unknown_optional_front").blob));
  assert.equal(front.unknown[0].bytes.length, 300);
  // a model may not hold a malformed or repeated unknown section, or one that does not fit
  const bad = [{ id: 0x40, scope: 0xff, bytes: [] }, { id: 0x90, scope: 4, bytes: [] }, { id: 0x90, scope: 0xff, bytes: [256] }];
  for (const u of bad) { const t = base2(); t.unknown = [u]; assert.throws(() => encodeSettings(t), SettingsError, JSON.stringify(u)); }
  const dup = base2(); dup.unknown = [{ id: 0x90, scope: 0xff, bytes: [] }, { id: 0x90, scope: 0xff, bytes: [1] }];
  assert.throws(() => encodeSettings(dup), SettingsError);
  const huge = base2(); huge.unknown = [{ id: 0x90, scope: 0xff, bytes: new Array(2000).fill(1) }];
  assert.throws(() => encodeSettings(huge), (e) => e.code === "length");
  const fits = base2(); fits.unknown = [{ id: 0x90, scope: 0xff, bytes: new Array(1700).fill(1) }];
  assert.ok(encodeSettings(fits).length <= FW_SETTINGS.v3MaxSize);
});

test("v3: a model that says nothing about the M6 members means 'none / default'", () => {
  const s = base2();
  for (const pr of s.profiles) { delete pr.dks; delete pr.morph; delete pr.socd; delete pr.pad; }
  delete s.device; delete s.unknown;
  assert.equal(hex(encodeSettings(s)), V.default);
});

test("v3: cross references, counts and shapes of the model are refused with a reason", () => {
  const slot = kslot[5];
  const mk = (f) => { const s = base2(); f(s); return s; };
  const why = (s) => { try { encodeSettings(s); } catch (e) { return `${e.code}`; } return null; };
  assert.equal(why(mk((s) => { s.profiles[1].layers[0][slot] = 0xed; })), "usage", "DKS key without a record");
  assert.equal(why(mk((s) => { s.profiles[1].layers[0][slot] = 0xec; s.profiles[1].args[0][slot] = [4, 0]; })), "usage", "Mod-Morph key without a record");
  assert.equal(why(mk((s) => { s.profiles[0].dks = new Array(9).fill(null); })), "record");
  assert.equal(why(mk((s) => { s.profiles[0].socd = [{ a: kslot[0], b: kslot[1], mode: 1, flags: 0 }, { a: kslot[1], b: kslot[2], mode: 1, flags: 0 }]; })), "record", "a key in two pairs");
  assert.equal(why(mk((s) => { s.profiles[0].socd = [{ a: 15, b: kslot[1], mode: 1, flags: 0 }]; })), "record", "a slot without a key");
  assert.equal(why(mk((s) => { s.profiles[0].pad.curves.pop(); })), "record");
  assert.equal(why(mk((s) => { s.device = { padMode: 3, filterMode: 0 }; })), "record");
  assert.equal(why(mk((s) => { s.profiles[0].dks = [{ tAct: 120, tBot: 0, flags: 0, acts: [[4, 1], [0, 0], [0, 0]] }]; })), "record");
  assert.equal(why(mk((s) => { s.profiles[0].dks = [{ tAct: 1.5, tBot: 0, flags: 0, acts: [[4, 1], [0, 0], [0, 0], [0, 0]] }]; })), "record");
  assert.equal(why(mk((s) => { s.profiles[0].socd = [0, 1, 2, 3, 4].map((i) => ({ a: kslot[2 * i], b: kslot[2 * i + 1], mode: 1, flags: 0 })); })), "record", "5 SOCD pairs");
  assert.equal(why(mk((s) => { s.profiles[0].morph = Array.from({ length: 9 }, () => ({ mask: 1, usage: 4, flags: 0 })); })), "record", "9 Mod-Morph records");
  assert.equal(why(mk((s) => { s.profiles[0].dks = Array.from({ length: 9 }, () => ({ tAct: 120, tBot: 0, flags: 0, acts: [[4, 1], [0, 0], [0, 0], [0, 0]] })); })), "record", "9 DKS records");
  assert.equal(why(base2()), null);
});

test("v3: whatever bytes arrive, decode answers with a SettingsError or a valid model (nothing else is ever thrown)", () => {
  let seed = 12345;
  const rnd = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed >>> 8; };
  const fixCrc = (b) => { const c = crc32(b.subarray(0, b.length - 4)); b.set([c & 255, (c >>> 8) & 255, (c >>> 16) & 255, c >>> 24], b.length - 4); };
  let ok = 0, bad = 0;
  for (let n = 0; n < 3000; n++) {
    const b = Uint8Array.from(richBlob);
    const hits = 1 + (rnd() % 4);
    for (let h = 0; h < hits; h++) {
      const pos = rnd() % 3 === 0 ? rnd() % 24 : rnd() % (b.length - 4);
      b[pos] = rnd() & 1 ? rnd() & 255 : b[pos] ^ (1 << (rnd() % 8));
    }
    fixCrc(b);
    try {
      const s = decodeSettings(b);
      ok++;
      assert.doesNotThrow(() => encodeSettings(s));
    } catch (e) {
      assert.ok(e instanceof SettingsError, `unexpected ${e}`);
      bad++;
    }
  }
  assert.ok(ok > 50 && bad > 50);
  for (let n = 0; n < 500; n++) {            // garbage behind a valid header and CRC
    const len = 20 + (rnd() % 300);
    const b = new Uint8Array(len);
    for (let i = 0; i < len; i++) b[i] = rnd() & 255;
    b.set([0x4b, 0x4d, 0x43, 0x53, 3, 0, len & 255, len >> 8], 0);
    b[9] = 4; b[10] = 4; b[11] = 61; b[12] = rnd() % 6; b[13] = b[14] = b[15] = 0;
    fixCrc(b);
    assert.throws(() => decodeSettings(b), SettingsError);
  }
  // input types
  for (const junk of [undefined, null, [], [1, 2, 3], new Uint8Array(0), "KMCS", {}]) assert.throws(() => decodeSettings(junk), SettingsError);
});
